import express, { type NextFunction, type Request, type Response } from "express";

type Product = { id: string; name: string; price: number };
const products: Product[] = [];

export const app = express();
app.use(express.json({ limit: "16kb" }));

function validateProduct(request: Request, response: Response, next: NextFunction) {
    const body = (request.body ?? {}) as { name?: unknown; price?: unknown };
    if (typeof body.name !== "string" || body.name.trim() === "") {
        next(Object.assign(new Error("A product name is required."), { status: 400, code: "invalid_name" }));
        return;
    }
    if (typeof body.price !== "number" || !Number.isFinite(body.price) || body.price < 0) {
        next(Object.assign(new Error("A non-negative price is required."), { status: 400, code: "invalid_price" }));
        return;
    }
    next();
}

app.post("/products", validateProduct, function createProduct(request, response) {
    const body = request.body as { name: string; price: number };
    const product = { id: String(products.length + 1), name: body.name, price: body.price };
    products.push(product);
    response.status(201).json(product);
});

app.use(function onError(error: Error & { status?: number; code?: string }, request: Request, response: Response, next: NextFunction) {
    const status = error.status ?? 500;
    response.status(status).json({ error: error.code ?? "internal" });
});
